    if n <= 0:
        return 1
    elif n == 1:
        return 2
    else:
        return 2 ** ((n - 1).bit_length())

def get_pell(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return 2 * get_pell(n - 1) + get_pell(n - 2)

def is_valid_parenthese(s):
    stack = []
    for c in s:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
    return not stack

def check_String(string):
