def validate(number):
    freq = [0] * 10
    while number > 0:
        digit = number % 10
        freq[digit] += 1
        number //= 10
    for i in range(10):
        if freq[i] > i:
            return False
    return True

def max_sub_array_sum_repeated(arr, n, k):
    repeated_arr = arr * k
    max_sum = float('-inf')
    current_sum = 0

    for i in range(len(repeated_arr)):
        current_sum += repeated_arr[i]
        if current_sum > max_sum:
