def frequency_Of_Smallest(n, arr):
    smallest = arr[0]
    freq = 1
    for i in range(1, n):
        if arr[i] < smallest:
            smallest = arr[i]
            freq = 1
        elif arr[i] == smallest:
            freq += 1
    return freq

def even_or_odd(hex_number):
