def is_Sub_Array(arr, sub_arr, n, m):
    if m > n:
        return False
    for i in range(n - m + 1):
        j = 0
        while j < m:
            if arr[i + j] != sub_arr[j]:
                break
            j += 1
        if j == m:
            return True
    return False

def perfect_squares(start, end):
    squares = []
    for i in range(start, end+1):
        if i**0.5 == int(i**0.5):
            squares.append(i)
    return squares

def prime_num(num):
    if num < 2:
        return False
    for i in range(2, num):
        if num % i == 0:
            return False
    return True

